class Policy {
  boolean allowed(User user, Request request) {
    if (user != null) {
      if (user.active()) {
        if (request != null) {
          if (request.ownerId() == user.id()) return true;
          else if (user.admin() && request.open()) return true;
          else if (user.support() && request.queue() != null) return true;
        }
      }
    }
    return false;
  }
}

